@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--bg:#101513;--panel:#171e1a;--panel2:#1d2520;--line:#28332c;--muted:#87928a;--text:#f0f3ef;--lime:#c8f169;--lime2:#acd94e;--orange:#f2a76e;--font:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}
*{box-sizing:border-box}html{background:var(--bg);scroll-behavior:smooth}body{margin:0;color:var(--text);font-family:var(--font);font-size:14px;background:var(--bg);-webkit-font-smoothing:antialiased}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible{outline:2px solid var(--lime);outline-offset:3px}.app-shell{min-height:100vh}.sidebar{width:252px;position:fixed;inset:0 auto 0 0;background:#141a16;border-right:1px solid #252e28;padding:29px 18px 20px;display:flex;flex-direction:column;z-index:10}.brand{display:flex;align-items:center;gap:12px;padding:0 12px;color:inherit;text-decoration:none}.brand-mark{height:27px;width:27px;position:relative;display:flex;align-items:flex-end;gap:3px;transform:skew(-22deg)}.brand-mark span{width:6px;border-radius:4px;background:var(--lime);display:block}.brand-mark span:nth-child(1){height:13px;opacity:.7}.brand-mark span:nth-child(2){height:21px;opacity:.86}.brand-mark span:nth-child(3){height:27px}.brand-name{font-family:var(--display);font-size:17px;font-weight:700;letter-spacing:-.7px}.brand-name span{font-weight:500;color:#9da79f}.club-switcher{margin:39px 1px 32px;padding:12px 10px;display:flex;align-items:center;gap:11px;background:#1a221d;border:1px solid #2a362e;border-radius:11px}.club-crest{width:35px;height:38px;display:grid;place-items:center;clip-path:polygon(10% 0,90% 0,86% 76%,50% 100%,14% 76%);background:linear-gradient(145deg,#d8fa87,#a6cd47);color:#182013;font-family:var(--display);font-weight:700;font-size:12px}.club-meta{flex:1;min-width:0}.club-meta strong{display:block;font-size:12px;font-weight:700}.club-meta small{display:block;margin-top:4px;color:#8e9b91;font-size:8px;letter-spacing:.75px;font-weight:700}.chevron{color:#97a196;font-size:16px;margin-top:-5px}.nav-label{font-size:9px;color:#6c7970;letter-spacing:1.25px;font-weight:800;padding:0 12px;margin-bottom:12px}.main-nav{display:grid;gap:5px}.nav-item{border:0;background:transparent;color:#9aa59d;display:flex;align-items:center;text-align:left;gap:12px;padding:12px 13px;border-radius:9px;font-size:12px;font-weight:600;transition:.18s}.nav-item:hover{background:#1b241e;color:#eef3ed}.nav-item.active{color:var(--lime);background:#242d25}.nav-icon{font-size:17px;width:18px;text-align:center;line-height:1}.nav-badge{margin-left:auto;background:#2d3b2e;border-radius:5px;font-size:9px;padding:3px 6px;color:#b9d985}.sidebar-bottom{margin-top:auto}.season-card{border:1px solid #2a352d;background:linear-gradient(145deg,#202a22,#1a211c);padding:14px 14px 12px;border-radius:10px;margin-bottom:20px}.season-top{display:flex;justify-content:space-between;color:#869488;font-size:8px;letter-spacing:.8px;font-weight:800}.tiny-star{color:var(--lime);font-size:15px}.season-card>strong{display:block;font-family:var(--display);font-size:14px;line-height:1.35;margin:12px 0}.season-progress{height:4px;background:#38443a;border-radius:9px;margin:12px 0 8px;overflow:hidden}.season-progress i{height:100%;width:30%;display:block;background:var(--lime);border-radius:8px}.season-card small{font-size:9px;color:#98a399}.season-card small b{color:#5d6b60;margin:0 4px}.settings-button{width:100%;margin-bottom:13px}.manager-profile{padding:15px 3px 0;border-top:1px solid #28312b;display:flex;align-items:center;gap:10px}.avatar,.top-avatar{display:grid;place-items:center;border-radius:50%;background:#44533d;color:#d4efa3;font-size:10px;font-weight:800}.avatar{height:32px;width:32px}.manager-profile strong{font-size:10px;display:block}.manager-profile small{font-size:9px;color:#859087;display:block;margin-top:3px}.more-button{margin-left:auto;background:transparent;border:0;color:#9ba79d;font-size:20px}.main-content{margin-left:252px;min-height:100vh;display:flex;flex-direction:column}.topbar{height:67px;border-bottom:1px solid #252e28;display:flex;align-items:center;justify-content:space-between;padding:0 44px;background:rgba(16,21,19,.93)}.breadcrumb{font-size:9px;letter-spacing:.9px;font-weight:800;color:#89958b}.breadcrumb i{font-style:normal;color:#4b584e;margin:0 11px}.breadcrumb b{color:#d7ddd7}.top-actions{display:flex;align-items:center;gap:18px}.season-pill{font-size:9px;letter-spacing:.55px;color:#adb6af;border:1px solid #303a33;border-radius:6px;padding:8px 11px;display:flex;align-items:center;gap:7px}.season-dot{width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 8px #c8f16977}.pill-divider{height:11px;border-left:1px solid #37423a;margin:0 4px}.icon-button{position:relative;border:0;background:transparent;color:#abb4ad;font-size:17px}.icon-button i{position:absolute;width:4px;height:4px;background:var(--orange);border-radius:100%;right:-2px;top:1px}.top-avatar{height:30px;width:30px;background:#303e33;color:#d8eac2}.mobile-menu{display:none}.page-wrap{width:min(1290px,100%);margin:0 auto;padding:32px 44px 40px;flex:1}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:25px}.eyebrow{display:flex;align-items:center;gap:10px;color:#9aa59c;font-size:9px;letter-spacing:1.1px;font-weight:800}.eyebrow-line{height:1px;width:24px;background:#455249}.page-heading h1{font-family:var(--display);font-size:31px;letter-spacing:-1.3px;margin:10px 0 5px;font-weight:600}.page-heading h1 span{font-size:18px;color:var(--lime);vertical-align:5px}.page-heading p{margin:0;color:#8e9a91;font-size:12px}.primary-button{background:var(--lime);color:#1a2415;border:0;border-radius:7px;font-size:11px;font-weight:800;display:flex;align-items:center;gap:10px;padding:12px 13px;box-shadow:0 4px 18px #c8f16914;transition:transform .18s,background .18s}.primary-button:hover{background:#d6ff82;transform:translateY(-1px)}.primary-button>span:first-child{font-size:14px}.button-arrow{font-size:16px;margin-left:7px}.footer{height:44px;border-top:1px solid #242d27;color:#68756b;display:flex;justify-content:space-between;align-items:center;padding:0 44px;font-size:8px;letter-spacing:.85px;font-weight:700}.footer b{font-size:12px;color:var(--lime);margin-left:5px}
/* dashboard */
.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(270px,.9fr);gap:17px;align-items:stretch}.match-card{min-height:376px;position:relative;overflow:hidden;border:1px solid #2d3b32;background:#17201b;border-radius:13px;isolation:isolate}.match-card:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(14,19,16,.22),rgba(14,19,16,.05) 37%,rgba(12,17,14,.68));z-index:-1}.match-canvas{position:absolute;inset:0;width:100%;height:100%;z-index:-2}.match-topline{position:absolute;top:18px;left:19px;right:19px;display:flex;justify-content:space-between;align-items:center;z-index:1}.live-tag{display:flex;align-items:center;gap:7px;border-radius:5px;background:#1d2b20d9;color:#d3ebaa;padding:7px 9px;font-size:8px;font-weight:800;letter-spacing:.8px;border:1px solid #435839}.live-tag i{width:6px;height:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 9px #c8f169}.match-round{font-size:9px;color:#c5cec7;font-weight:700;letter-spacing:.6px;text-shadow:0 1px 8px #000}.match-summary{position:absolute;left:23px;right:23px;bottom:20px;z-index:1}.score-line{display:flex;align-items:center;gap:12px;margin-bottom:13px}.team-side{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:800;letter-spacing:.4px}.team-side.away{margin-left:auto;flex-direction:row-reverse;text-align:right}.mini-crest{width:26px;height:29px;display:grid;place-items:center;clip-path:polygon(9% 0,91% 0,86% 75%,50% 100%,14% 75%);font-family:var(--display);font-size:8px;font-weight:700;background:var(--lime);color:#1c2518}.mini-crest.opponent{background:#ea8665;color:#2d1712}.score-number{font-family:var(--display);font-size:25px;font-weight:700;letter-spacing:-1px}.score-dash{color:#a7b0a9;font-size:16px}.match-meta-row{border-top:1px solid #ffffff31;padding-top:11px;display:flex;align-items:center;gap:13px;color:#d0d8d1;font-size:9px}.live-min{color:var(--lime);font-weight:800;min-width:32px}.match-location{margin-left:auto;color:#bec8bf}.match-controls{display:flex;gap:5px}.match-control{border:1px solid #ffffff39;border-radius:5px;background:#121b17a6;color:#e5ebe5;width:27px;height:24px;font-size:10px}.match-control:hover{background:#c8f169;color:#182014}.match-aside{display:flex;flex-direction:column;gap:13px}.next-match-card,.team-form-card,.quick-actions-card{border:1px solid #2a352e;background:#171e1a;border-radius:12px;padding:17px}.card-kicker{display:flex;align-items:center;justify-content:space-between;color:#829087;font-size:8px;font-weight:800;letter-spacing:1px}.card-kicker a{color:var(--lime);text-decoration:none;font-size:9px;letter-spacing:0}.next-opponent{display:flex;align-items:center;gap:12px;margin:18px 0 14px}.opponent-logo{height:43px;width:41px;clip-path:polygon(8% 0,92% 0,86% 78%,50% 100%,14% 78%);display:grid;place-items:center;background:linear-gradient(145deg,#ef9569,#c65a42);font-size:10px;font-family:var(--display);font-weight:700;color:#371c14}.next-opponent div:nth-child(2){flex:1}.next-opponent strong{display:block;font-family:var(--display);font-size:13px}.next-opponent small{display:block;color:#8b978e;font-size:9px;margin-top:4px}.opponent-rating{font-size:10px;color:#d5ddd6;font-weight:700}.next-details{border-top:1px solid #2b362e;padding-top:11px;display:flex;justify-content:space-between;color:#8d998f;font-size:9px}.next-details b{color:#d4dbd4}.form-list{display:flex;justify-content:space-between;margin-top:15px;gap:6px}.form-result{width:25px;height:25px;border-radius:6px;display:grid;place-items:center;font-size:9px;font-weight:800}.form-result.w{background:#2c4229;color:#c5f079}.form-result.d{background:#343c35;color:#bbc4bc}.form-result.l{background:#462d2a;color:#f19c83}.form-caption{display:flex;justify-content:space-between;color:#77847a;font-size:8px;margin-top:10px}.form-caption b{color:#c1cbc2}.quick-actions-card{padding:15px 17px}.quick-row{display:flex;align-items:center;gap:10px;margin-top:13px}.quick-row button{flex:1;border:1px solid #354238;background:#202921;border-radius:6px;padding:9px 8px;color:#c8d1c9;font-weight:700;font-size:9px;text-align:left}.quick-row button:hover{border-color:#819e57;color:var(--lime)}.quick-row button span{font-size:14px;margin-right:6px;color:var(--lime)}.stats-strip{display:grid;grid-template-columns:repeat(4,1fr);margin-top:16px;border:1px solid #2a352e;background:#171e1a;border-radius:11px;overflow:hidden}.stat-cell{padding:15px 18px;position:relative}.stat-cell+.stat-cell{border-left:1px solid #2a352e}.stat-label{font-size:8px;color:#87938a;letter-spacing:.8px;font-weight:800}.stat-value{display:flex;align-items:baseline;gap:8px;margin-top:8px}.stat-value strong{font-family:var(--display);font-size:21px;letter-spacing:-.8px}.stat-value small{font-size:9px;color:#839087}.stat-value .positive{color:var(--lime)}.stat-value .neutral{color:#f2b484}.stat-icon{position:absolute;right:16px;top:18px;color:#627368;font-size:17px}.news-ticker{display:flex;align-items:center;gap:11px;margin-top:16px;padding:11px 14px;border:1px solid #29342c;border-radius:8px;background:#171d19;color:#aab5ac;font-size:10px}.news-ticker b{font-size:8px;letter-spacing:.9px;color:var(--lime);border-right:1px solid #3b473d;padding-right:10px;white-space:nowrap}.news-ticker span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.news-ticker em{font-style:normal;color:#657269;font-size:9px;margin-left:auto;white-space:nowrap}

/* screens */
.screen-title-row{display:flex;align-items:flex-end;justify-content:space-between;margin:5px 0 17px}.screen-title-row h2{font-family:var(--display);font-size:20px;letter-spacing:-.7px;margin:0}.screen-title-row p{margin:5px 0 0;font-size:10px;color:#87938a}.surface{background:#171e1a;border:1px solid #2a352e;border-radius:11px;padding:17px}.squad-layout{display:grid;grid-template-columns:1.55fr .85fr;gap:15px}.squad-table{width:100%;border-collapse:collapse}.squad-table th{text-align:left;color:#768279;font-size:8px;letter-spacing:.8px;padding:9px 10px;border-bottom:1px solid #303a33}.squad-table td{padding:10px;border-bottom:1px solid #252e28;font-size:10px;color:#c5cec6}.squad-table tr:last-child td{border-bottom:0}.player-name{display:flex;align-items:center;gap:9px;font-weight:700;color:#e5eae5!important}.player-avatar{height:28px;width:28px;display:grid;place-items:center;border-radius:7px;background:#29382d;color:#c5ed76;font-size:8px;font-weight:800}.player-avatar.warm{background:#382f27;color:#edb879}.position-tag{border-radius:4px;background:#252e28;padding:4px 5px;color:#9da99f;font-size:8px;font-weight:700}.rating{font-family:var(--display);font-weight:700}.rating.high{color:var(--lime)}.condition{width:62px;height:4px;border-radius:4px;background:#313d34;overflow:hidden;display:inline-block;vertical-align:middle}.condition i{height:100%;display:block;background:var(--lime);border-radius:4px}.condition.low i{background:var(--orange)}.squad-side{display:flex;flex-direction:column;gap:13px}.chemistry{display:flex;align-items:center;gap:13px;margin:16px 0}.chemistry-ring{height:53px;width:53px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(closest-side,#171e1a 72%,transparent 73%),conic-gradient(var(--lime) 0 82%,#374137 82% 100%);font-family:var(--display);font-weight:700;font-size:13px;color:#e7eddf}.chemistry strong{font-size:11px}.chemistry p{font-size:9px;color:#859188;margin:4px 0 0}.role-list{display:grid;gap:8px}.role-row{display:flex;justify-content:space-between;color:#9aa59c;font-size:9px}.role-row b{color:#dce4dc}.reserve-list{display:grid;gap:8px;margin-top:12px}.reserve-item{display:flex;align-items:center;gap:8px;border-top:1px solid #2a342c;padding-top:8px}.reserve-item strong{font-size:9px}.reserve-item small{margin-left:auto;color:#9eaa9f;font-size:9px}
.tactics-layout{display:grid;grid-template-columns:1.1fr .9fr;gap:15px}.formation-board{height:365px;position:relative;overflow:hidden;border:1px solid #314132;border-radius:9px;background:repeating-linear-gradient(0deg,#23452b 0,#23452b 42px,#285030 42px,#285030 84px)}.formation-board:before{content:'';position:absolute;inset:0 12%;border:1px solid #ffffff53}.formation-board:after{content:'';position:absolute;left:12%;right:12%;top:50%;border-top:1px solid #ffffff53}.pitch-circle{position:absolute;width:100px;height:100px;border:1px solid #ffffff53;border-radius:50%;left:calc(50% - 50px);top:calc(50% - 50px)}.pitch-box{position:absolute;width:45%;height:18%;left:27.5%;border:1px solid #ffffff53}.pitch-box.top{top:0;border-top:0}.pitch-box.bottom{bottom:0;border-bottom:0}.formation-player{position:absolute;transform:translate(-50%,-50%);border:0;background:#d6fa8a;color:#24301e;border-radius:50%;height:32px;width:32px;box-shadow:0 3px 8px #1119;font-size:8px;font-weight:800;z-index:2}.formation-player:hover{transform:translate(-50%,-50%) scale(1.13)}.formation-label{position:absolute;left:12px;top:11px;font-size:8px;font-weight:800;letter-spacing:1px;color:#d5e6c8;background:#1a2a1ca8;padding:6px 8px;border-radius:4px;z-index:3}.tactics-controls{display:grid;gap:13px}.control-group label{font-size:9px;letter-spacing:.7px;color:#87948b;font-weight:800;display:block;margin-bottom:8px}.segmented{display:flex;gap:5px}.segmented button{flex:1;background:#202822;border:1px solid #313d33;border-radius:6px;padding:9px 6px;color:#aab5ab;font-size:9px;font-weight:700}.segmented button.selected{background:#33422e;border-color:#78964d;color:#d7f3a5}.tactic-note{font-size:9px;color:#859188;line-height:1.55;padding:11px;background:#202821;border-radius:7px}.tactic-note b{color:var(--lime)}.tactic-actions{display:flex;gap:8px}.tactic-actions button{flex:1;justify-content:center}
.training-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.training-card{border:1px solid #2b362f;background:#171e1a;border-radius:11px;padding:16px;min-height:180px;display:flex;flex-direction:column}.training-icon{height:34px;width:34px;display:grid;place-items:center;background:#2c382b;color:var(--lime);border-radius:9px;font-size:17px}.training-card h3{font-family:var(--display);font-size:13px;margin:14px 0 5px}.training-card p{color:#869289;font-size:9px;line-height:1.6;margin:0 0 12px}.training-foot{margin-top:auto;display:flex;justify-content:space-between;align-items:center}.training-foot span{font-size:9px;color:#b1bdb2}.training-foot button{background:#29352a;border:1px solid #3a4b38;border-radius:5px;padding:7px 9px;color:#d7f4a1;font-size:8px;font-weight:800}.training-foot button:hover{background:#364631}.training-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:15px}.training-summary .surface{padding:13px}.training-summary small{font-size:8px;letter-spacing:.7px;color:#859188;font-weight:800}.training-summary strong{display:block;font-family:var(--display);margin-top:7px;font-size:17px}.training-summary strong span{font-family:var(--font);font-size:9px;color:#9aa69c;font-weight:500}
.league-layout{display:grid;grid-template-columns:1.35fr .8fr;gap:15px}.league-table{width:100%;border-collapse:collapse}.league-table th{text-align:left;padding:9px;color:#7e8b81;font-size:8px;letter-spacing:.7px;border-bottom:1px solid #303a33}.league-table td{padding:10px 9px;border-bottom:1px solid #28312a;font-size:9px;color:#b9c3ba}.league-table tr:last-child td{border-bottom:0}.league-table tr.our-club{background:#263326}.league-table tr.our-club td{color:#e1edda;font-weight:800}.league-table td:first-child{width:25px;color:#7d8b7f}.league-club{display:flex;align-items:center;gap:7px;font-weight:700}.table-dot{height:19px;width:19px;border-radius:5px;background:#34443a;display:grid;place-items:center;color:#d2e89f;font-size:7px}.table-dot.red{background:#49332e;color:#f0a17e}.league-side{display:grid;gap:13px;align-content:start}.fixture-row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #2a342c;padding:11px 0;color:#d0d8d0;font-size:9px}.fixture-row:first-of-type{margin-top:12px}.fixture-row span:nth-child(2){color:#849087;font-size:8px}.fixture-row b{font-family:var(--display);font-size:10px}
