const state={view:'inicio',minute:0,homeScore:0,awayScore:0,playing:false,ended:false,speed:1,formation:saved.formation||'4-3-3',mentality:saved.mentality||'Equilibrado',pressing:saved.pressing||'Médio',training:saved.training||0,budget:saved.budget??18.4,round:saved.round||7,played:saved.played||false,points:saved.points||9,table:initialTable,goalEvents:[],selectedPlayer:null,feed:'O elenco está concentrado. A torcida já começa a chegar ao estádio.',
