function setView(view){state.view=view;$$('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#crumbTitle').textContent=({inicio:'VISÃO GERAL',elenco:'MEU ELENCO',taticas:'TÁTICAS',treino:'TREINAMENTO',liga:'CAMPEONATO'})[view];renderView();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function renderView(){const root=$('#viewContent');if(state.view==='inicio')root.innerHTML=dashboardHTML();if(state.view==='elenco')root.innerHTML=squadHTML();if(state.view==='taticas')root.innerHTML=tacticsHTML();if(state.view==='treino')root.innerHTML=trainingHTML();if(state.view==='liga')root.innerHTML=leagueHTML();bindView();if(state.view==='inicio')setupCanvas()}
function dashboardHTML(){
 const minute=state.ended?'FIM':state.playing?`${state.minute}’`:'HOJE · 19:00';
 const matchState=state.ended?'PARTIDA ENCERRADA':state.playing?'AO VIVO':'DIA DE JOGO';
 const home=state.played&&state.ended?state.homeScore:'—', away=state.played&&state.ended?state.awayScore:'—';
 const latest=state.goalEvents.at(-1)||state.feed;
 return `<div class="dashboard-grid"><section class="match-card"><canvas id="matchCanvas" class="match-canvas" aria-label="Animação 3D de partida de futebol"></canvas><div class="match-topline"><span class="live-tag"><i></i><b>${matchState}</b></span><span class="match-round">BRASILEIRÃO · RODADA ${state.round}</span></div><div class="match-summary"><div class="score-line"><div class="team-side"><span class="mini-crest">RV</span><span>RIO VERDE</span></div><span class="score-number" id="homeScore">${home}</span><span class="score-dash">:</span><span class="score-number" id="awayScore">${away}</span><div class="team-side away"><span class="mini-crest opponent">AN</span><span>ATLÉTICO NORTE</span></div></div><div class="match-meta-row"><span class="live-min" id="minuteLabel">${minute}</span><span id="matchFeed">${latest}</span><span class="match-location">◉ Estádio Aurora</span><div class="match-controls"><button class="match-control" id="pauseMatch" aria-label="Pausar partida">Ⅱ</button><button class="match-control" id="speedMatch" aria-label="Acelerar partida">${state.speed}×</button></div></div></div></section>
 <aside class="match-aside"><section class="next-match-card"><div class="card-kicker"><span>PRÓXIMO DESAFIO</span><a href="#liga" data-goto="liga">VER AGENDA ↗</a></div><div class="next-opponent"><div class="opponent-logo">AN</div><div><strong>Atlético Norte</strong><small>7º lugar <b>·</b> Fora de casa</small></div><span class="opponent-rating">76 <small>OVR</small></span></div><div class="next-details"><span><b>Hoje, 19:00</b></span><span>Estádio Aurora</span><span>⛅ 23°</span></div></section>
 <section class="team-form-card"><div class="card-kicker"><span>FORMA RECENTE</span><a href="#liga" data-goto="liga">ÚLTIMOS JOGOS</a></div><div class="form-list"><span class="form-result w">V</span><span class="form-result d">E</span><span class="form-result w">V</span><span class="form-result l">D</span><span class="form-result w">V</span></div><div class="form-caption"><span>3 vitórias nos últimos 5</span><b>9 pts</b></div></section>
 <section class="quick-actions-card"><div class="card-kicker"><span>ATALHOS DO MISTER</span><span>✦</span></div><div class="quick-row"><button data-goto="elenco"><span>♙</span> Escalação</button><button data-goto="taticas"><span>⌗</span> Ajustar tática</button><button data-goto="treino"><span>↗</span> Treinar time</button></div></section></aside></div>
 <section class="stats-strip"><div class="stat-cell"><span class="stat-label">POSIÇÃO NA LIGA</span><span class="stat-icon">♜</span><div class="stat-value"><strong>7º</strong><small class="positive">↑ 2 posições</small></div></div><div class="stat-cell"><span class="stat-label">PONTOS</span><span class="stat-icon">◈</span><div class="stat-value"><strong>${state.points}</strong><small>em 6 jogos</small></div></div><div class="stat-cell"><span class="stat-label">ORÇAMENTO</span><span class="stat-icon">◉</span><div class="stat-value"><strong>€ ${state.budget.toFixed(1)}<small style="font-size:11px">M</small></strong><small class="positive">saudável</small></div></div><div class="stat-cell"><span class="stat-label">FORÇA DO ELENCO</span><span class="stat-icon">✧</span><div class="stat-value"><strong>78</strong><small class="neutral">bom nível</small></div></div></section>
 <div class="news-ticker"><b>NOTÍCIA DO CLUBE</b><span id="newsLine">${state.ended?'A torcida vibra com o resultado. O elenco já pensa no próximo desafio.':'Enzo Carvalho está em grande fase e pode ser decisivo no jogo de hoje.'}</span><em>há 2h</em></div>`
}
function squadHTML(){const starters=players.slice(0,11);return `<div class="screen-title-row"><div><h2>Primeiro time</h2><p>Onze prontos para defender o escudo. Toque em dois jogadores para trocar.</p></div><button class="primary-button" id="saveLineup">✓ <b>Salvar escalação</b></button></div><div class="squad-layout"><section class="surface"><table class="squad-table"><thead><tr><th>JOGADOR</th><th>POS.</th><th>IDADE</th><th>GER</th><th class="hide-mobile">CONDIÇÃO</th></tr></thead><tbody>${starters.map((p,i)=>`<tr data-player="${i}" tabindex="0"><td class="player-name"><span class="player-avatar ${i===0?'warm':''}">${p.num}</span>${p.name}</td><td><span class="position-tag">${p.pos}</span></td><td>${[29,25,27,26,24,28,23,22,25,24,23][i]}</td><td class="rating ${p.rating>=79?'high':''}">${p.rating}</td><td class="hide-mobile"><span class="condition ${p.condition<86?'low':''}"><i style="width:${p.condition}%"></i></span> <small>${p.condition}%</small></td></tr>`).join('')}</tbody></table><div class="reserve-list"><div class="card-kicker"><span>NO BANCO</span><span>3 JOGADORES</span></div>${players.slice(11).map(p=>`<div class="reserve-item"><span class="player-avatar">${p.num}</span><strong>${p.name}</strong><span class="position-tag">${p.pos}</span><small>${p.rating} GER</small></div>`).join('')}</div></section><aside class="squad-side"><section class="surface"><div class="card-kicker"><span>QUÍMICA DO TIME</span><span style="color:var(--lime)">MUITO BOA</span></div><div class="chemistry"><div class="chemistry-ring">82</div><div><strong>Conexão em campo</strong><p>O time está entrosado e confiante.</p></div></div><div class="role-list"><div class="role-row"><span>Ataque</span><b>80 <span style="color:var(--lime)">↑</span></b></div><div class="role-row"><span>Meio-campo</span><b>80</b></div><div class="role-row"><span>Defesa</span><b>76</b></div><div class="role-row"><span>Goleiro</span><b>78</b></div></div></section><section class="surface"><div class="card-kicker"><span>CAPITÃO</span><span>BRAÇADEIRA</span></div><div class="reserve-item" style="border:0;margin-top:8px"><span class="player-avatar warm">10</span><strong>Enzo Carvalho</strong><small>MEI · 83 GER</small></div><p style="font-size:9px;color:#859188;line-height:1.55;margin:10px 0 0">Líder técnico e referência para os mais jovens.</p></section><section class="surface"><div class="card-kicker"><span>CLIMA DO ELENCO</span><span style="color:var(--lime)">☺ POSITIVO</span></div><p style="font-size:9px;color:#9aa59b;line-height:1.6;margin:11px 0 0">O grupo está unido e motivado para buscar a vitória.</p></section></aside></div>`}

function tacticsHTML(){return `<div class="screen-title-row"><div><h2>Quadro tático</h2><p>Monte seu plano de jogo. Cada escolha muda o comportamento do time.</p></div><button class="primary-button" id="saveTactics">✓ <b>Aplicar tática</b></button></div><div class="tactics-layout"><section class="surface"><div class="card-kicker"><span>FORMAÇÃO · <b id="formationName" style="color:#e4ece4">${state.formation}</b></span><span style="color:var(--lime)">ONZE INICIAL</span></div><div class="formation-board" id="formationBoard"><span class="formation-label">RIO VERDE FC</span><div class="pitch-circle"></div><div class="pitch-box top"></div><div class="pitch-box bottom"></div>${formationPlayers()}</div><div style="font-size:8px;color:#7e8a81;margin-top:8px">Toque no campo para trocar a formação de jogo.</div></section><section class="surface tactics-controls"><div class="control-group"><label>FORMAÇÃO</label><div class="segmented" data-setting="formation">${['4-3-3','4-4-2','3-5-2','4-2-3-1'].map(x=>`<button class="${state.formation===x?'selected':''}" data-value="${x}">${x}</button>`).join('')}</div></div><div class="control-group"><label>MENTALIDADE</label><div class="segmented" data-setting="mentality">${['Defensiva','Equilibrado','Ofensiva'].map(x=>`<button class="${state.mentality===x?'selected':''}" data-value="${x}">${x}</button>`).join('')}</div></div><div class="control-group"><label>PRESSÃO</label><div class="segmented" data-setting="pressing">${['Baixo','Médio','Alto'].map(x=>`<button class="${state.pressing===x?'selected':''}" data-value="${x}">${x}</button>`).join('')}</div></div><div class="tactic-note"><b>LEITURA DO AUXILIAR</b><br>${tacticMessage()}</div><div class="tactic-actions"><button class="secondary-button" id="resetTactics">↺ Padrão</button><button class="secondary-button" data-goto="elenco">♙ Escalação</button></div></section></div>`}
function formationPlayers(){const coords=formations[state.formation];return coords.map((xy,i)=>`<button class="formation-player" style="left:${xy[0]}%;top:${xy[1]}%" title="${players[i].name} · ${players[i].pos}">${players[i].num}</button>`).join('')}
function tacticMessage(){if(state.mentality==='Ofensiva'&&state.pressing==='Alto')return 'Time agressivo e vertical. Atenção ao espaço nas costas da defesa.';if(state.mentality==='Defensiva')return 'Bloco compacto para proteger o resultado e sair rápido no contra-ataque.';if(state.formation==='3-5-2')return 'Alas serão fundamentais para dar amplitude e recompor na defesa.';return 'Boa estrutura para controlar o meio e acelerar pelos lados.'}
function trainingHTML(){const drills=[['◉','Finalização','Aumente a precisão e a confiança dos atacantes.','ATAQUE'],['⌗','Posse de bola','Melhore o passe curto e o controle no meio.','TÉCNICA'],['⬡','Organização defensiva','Compactação, cobertura e bola parada defensiva.','DEFESA'],['↗','Transição rápida','Ganhe velocidade para surpreender no contra-ataque.','TÁTICA'],['✧','Recuperação','Descanso ativo para recuperar energia do elenco.','FÍSICO'],['♙','Bolas paradas','Ensaios de escanteio e cobranças de falta.','ESPECIAL']];return `<div class="screen-title-row"><div><h2>Centro de treinamento</h2><p>Escolha uma sessão para preparar o time para a próxima partida.</p></div><span class="position-tag" style="font-size:9px;padding:8px">SEMANA ${Math.ceil(state.round/2)} · 3 SESSÕES DISPONÍVEIS</span></div><div class="training-grid">${drills.map((d,i)=>`<article class="training-card"><div class="training-icon">${d[0]}</div><h3>${d[1]}</h3><p>${d[2]}</p><div class="training-foot"><span>${d[3]}</span><button data-training="${i}">${state.training===i?'✓ TREINADO':'INICIAR SESSÃO'}</button></div></article>`).join('')}</div><div class="training-summary"><div class="surface"><small>INTENSIDADE DA SEMANA</small><strong>${state.training<0?'Leve':'Moderada'} <span>· equilibrada</span></strong></div><div class="surface"><small>CONDIÇÃO MÉDIA</small><strong>90% <span class="positive">↑ muito boa</span></strong></div><div class="surface"><small>PRÓXIMA PARTIDA</small><strong>Hoje <span>· Atlético Norte</span></strong></div></div>`}
function leagueHTML(){const rows=[...initialTable];if(state.points>9)rows[6][1]=state.points;return `<div class="screen-title-row"><div><h2>Brasileirão Série A</h2><p>Temporada 2025/26 · A disputa está só começando.</p></div><span class="position-tag" style="font-size:9px;padding:8px">RODADA ${state.round} DE 38</span></div><div class="league-layout"><section class="surface"><div class="card-kicker"><span>TABELA DE CLASSIFICAÇÃO</span><span>ATUALIZADA AGORA</span></div><table class="league-table"><thead><tr><th>#</th><th>CLUBE</th><th>J</th><th>SG</th><th>PTS</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i===6?'our-club':''}"><td>${i+1}</td><td><span class="league-club"><span class="table-dot ${i===6?'':'red'}">${r[0].split(' ').map(x=>x[0]).slice(0,2).join('')}</span>${r[0]}</span></td><td>${i===6?6:7}</td><td>${[9,6,5,4,3,2,1,0,-1,-3][i]}</td><td>${i===6?state.points:r[1]}</td></tr>`).join('')}</tbody></table><div style="font-size:8px;color:#819087;margin-top:12px">✦ Libertadores &nbsp;&nbsp; ▪ Sul-Americana &nbsp;&nbsp; ▾ Rebaixamento</div></section><aside class="league-side"><section class="surface"><div class="card-kicker"><span>PRÓXIMOS JOGOS</span><span>RIO VERDE FC</span></div><div class="fixture-row"><span>HOJE · 19:00</span><b>Rio Verde <span style="color:#69766c">×</span> Atlético Norte</b><span>FORA</span></div><div class="fixture-row"><span>DOM · 28 SET</span><b>Rio Verde <span style="color:#69766c">×</span> Santa Cruz</b><span>CASA</span></div><div class="fixture-row"><span>SÁB · 04 OUT</span><b>Estrela do Sul <span style="color:#69766c">×</span> Rio Verde</b><span>FORA</span></div></section><section class="surface"><div class="card-kicker"><span>OBJETIVO DA DIRETORIA</span><span style="color:var(--lime)">✦</span></div><h3 style="font-family:var(--display);font-size:16px;margin:14px 0 5px">Vaga na Libertadores</h3><p style="color:#8f9b91;font-size:9px;line-height:1.55">Termine entre os 6 primeiros para garantir a classificação.</p><div class="season-progress"><i style="width:${Math.min(100,state.points*3)}%"></i></div><div class="role-row"><span>Posição atual</span><b>7º lugar</b></div></section><section class="surface"><div class="card-kicker"><span>ARTILHEIRO DO TIME</span><span>ATUALIZADO</span></div><div class="reserve-item" style="border:0;margin-top:9px"><span class="player-avatar warm">9</span><strong>João Pedro</strong><small>5 GOLS</small></div></section></aside></div>`}

function bindView(){
 $$('[data-goto]').forEach(x=>x.addEventListener('click',e=>{e.preventDefault();setView(x.dataset.goto)}));
 if(state.view==='inicio'){
  $('#pauseMatch')?.addEventListener('click',()=>{if(!state.playing){showToast('A partida ainda não começou. Toque em “Preparar para o jogo”.');return}state.playing=false;clearInterval(matchTimer);showToast('Partida pausada. Toque em continuar para retomar.');renderView()});
  $('#speedMatch')?.addEventListener('click',()=>{state.speed=state.speed===1?2:state.speed===2?3:1;$('#speedMatch').textContent=`${state.speed}×`;if(state.playing)startMatchTimer()});
  $$('.match-control').forEach(x=>x.addEventListener('click',e=>e.stopPropagation()));
 }
