const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];

const players = [
 {name:'Lucas Andrade',pos:'GL',num:1,rating:78,condition:94},{name:'Rafael Nunes',pos:'LD',num:2,rating:74,condition:91},{name:'Caio Martins',pos:'ZAG',num:3,rating:76,condition:87},{name:'Bruno Lima',pos:'ZAG',num:4,rating:79,condition:90},{name:'Igor Santos',pos:'LE',num:6,rating:73,condition:93},{name:'Pedro Henrique',pos:'VOL',num:5,rating:77,condition:84},{name:'Matheus Costa',pos:'MC',num:8,rating:81,condition:88},{name:'Enzo Carvalho',pos:'MEI',num:10,rating:83,condition:95},{name:'Gabriel Rocha',pos:'PD',num:7,rating:79,condition:89},{name:'João Pedro',pos:'ATA',num:9,rating:82,condition:86},{name:'Vitor Oliveira',pos:'PE',num:11,rating:78,condition:92},{name:'Davi Ferreira',pos:'ATA',num:19,rating:74,condition:100},{name:'Felipe Azevedo',pos:'MC',num:18,rating:75,condition:100},{name:'André Luiz',pos:'ZAG',num:14,rating:72,condition:100}
];
const formations={'4-3-3':[[50,89],[17,72],[39,77],[61,77],[83,72],[36,57],[50,60],[64,57],[18,31],[50,23],[82,31]],'4-4-2':[[50,89],[17,72],[39,77],[61,77],[83,72],[17,52],[39,59],[61,59],[83,52],[37,29],[63,29]],'3-5-2':[[50,89],[27,73],[50,78],[73,73],[12,53],[31,58],[50,54],[69,58],[88,53],[37,29],[63,29]],'4-2-3-1':[[50,89],[17,72],[39,77],[61,77],[83,72],[39,62],[61,62],[20,38],[50,42],[80,38],[50,23]]};
const initialTable=[['Atlético Norte',15],['União da Serra',14],['Porto Azul',13],['Estrela do Sul',12],['Ferroviária',11],['Real Central',10],['Rio Verde FC',9],['Náutico Imperial',8],['Vila Nova',7],['Santa Cruz',6]];
const saved=(()=>{try{return JSON.parse(localStorage.getItem('aurora-save'))||{}}catch{return {}}})();
const state={view:'inicio',minute:0,homeScore:0,awayScore:0,playing:false,ended:false,speed:1,formation:saved.formation||'4-3-3',mentality:saved.mentality||'Equilibrado',pressing:saved.pressing||'Médio',training:saved.training??-1,budget:saved.budget??18.4,round:saved.round||7,played:saved.played||false,points:saved.points||9,table:initialTable,goalEvents:[],selectedPlayer:null,feed:'O elenco está concentrado. A torcida já começa a chegar ao estádio.',opp:'Atlético Norte',oppShort:'AN'};
let matchTimer=null,toastTimer=null,canvasFrame=null,canvasCtx=null;
function save(){localStorage.setItem('aurora-save',JSON.stringify({formation:state.formation,mentality:state.mentality,pressing:state.pressing,training:state.training,budget:state.budget,round:state.round,played:state.played,points:state.points}))}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function setView(view){state.view=view;$$('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#crumbTitle').textContent=({inicio:'VISÃO GERAL',elenco:'MEU ELENCO',taticas:'TÁTICAS',treino:'TREINAMENTO',liga:'CAMPEONATO'})[view];renderView();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function renderView(){const root=$('#viewContent');if(state.view==='inicio')root.innerHTML=dashboardHTML();if(state.view==='elenco')root.innerHTML=squadHTML();if(state.view==='taticas')root.innerHTML=tacticsHTML();if(state.view==='treino')root.innerHTML=trainingHTML();if(state.view==='liga')root.innerHTML=leagueHTML();bindView();if(state.view==='inicio')setupCanvas()}

