// Aurora Manager — jogo de gestão de futebol responsivo.
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const roster=[
 ['Lucas Andrade','GL',1,78],['Rafael Nunes','LD',2,74],['Caio Martins','ZAG',3,76],['Bruno Lima','ZAG',4,79],['Igor Santos','LE',6,73],['Pedro Henrique','VOL',5,77],['Matheus Costa','MC',8,81],['Enzo Carvalho','MEI',10,83],['Gabriel Rocha','PD',7,79],['João Pedro','ATA',9,82],['Vitor Oliveira','PE',11,78],['Davi Ferreira','ATA',19,74],['Felipe Azevedo','MC',18,75],['André Luiz','ZAG',14,72]
].map(([name,pos,num,rating],i)=>({name,pos,num,rating,condition:[94,91,87,90,93,84,88,95,89,86,92,100,100,100][i]}));
const initialTable=[['Atlético Norte',15],['União da Serra',14],['Porto Azul',13],['Estrela do Sul',12],['Ferroviária',11],['Real Central',10],['Rio Verde FC',9],['Náutico Imperial',8],['Vila Nova',7],['Santa Cruz',6]];
const formations={'4-3-3':[[50,89],[17,72],[39,77],[61,77],[83,72],[36,57],[50,60],[64,57],[18,31],[50,23],[82,31]],'4-4-2':[[50,89],[17,72],[39,77],[61,77],[83,72],[17,52],[39,59],[61,59],[83,52],[37,29],[63,29]],'3-5-2':[[50,89],[27,73],[50,78],[73,73],[12,53],[31,58],[50,54],[69,58],[88,53],[37,29],[63,29]],'4-2-3-1':[[50,89],[17,72],[39,77],[61,77],[83,72],[39,62],[61,62],[20,38],[50,42],[80,38],[50,23]]};
let saved={};try{saved=JSON.parse(localStorage.getItem('aurora-save'))||{}}catch{}
const state={view:'inicio',minute:0,homeScore:0,awayScore:0,playing:false,played:!!saved.played,ended:!!saved.played,speed:1,formation:saved.formation||'4-3-3',mentality:saved.mentality||'Equilibrado',pressing:saved.pressing||'Médio',training:saved.training??-1,budget:saved.budget??18.4,round:saved.round||7,points:saved.points??9,events:[],feed:'O elenco está concentrado. A torcida já começa a chegar ao estádio.',selected:null};
let matchTimer=null,toastTimer=null,raf=null,ctx=null;
function save(){try{localStorage.setItem('aurora-save',JSON.stringify({formation:state.formation,mentality:state.mentality,pressing:state.pressing,training:state.training,budget:state.budget,round:state.round,played:state.played,points:state.points}))}catch{}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function setView(view){state.view=view;$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumbTitle').textContent=({inicio:'VISÃO GERAL',elenco:'MEU ELENCO',taticas:'TÁTICAS',treino:'TREINAMENTO',liga:'CAMPEONATO'})[view];render();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function render(){const root=$('#viewContent');root.innerHTML=({inicio:dashboardHTML,elenco:squadHTML,taticas:tacticsHTML,treino:trainingHTML,liga:leagueHTML}[state.view]());bindView();if(state.view==='inicio')setupCanvas()}

