function dashboardHTML(){
 const minute=state.ended?'FIM':state.playing?`${state.minute}’`:'HOJE · 19:00';
 const matchState=state.ended?'PARTIDA ENCERRADA':state.playing?'AO VIVO':'DIA DE JOGO';
 const home=state.played&&state.ended?state.homeScore:'—',away=state.played&&state.ended?state.awayScore:'—';
 const latest=state.events.at(-1)||state.feed;
 const action=state.playing?'Pausar partida':state.ended?'Próxima rodada':'Começar partida';
 return `<div class="dashboard-grid">
  <section class="match-card">
   <canvas id="matchCanvas" class="match-canvas" aria-label="Animação de partida de futebol"></canvas>
   <div class="match-topline"><span class="live-tag"><i></i><b>${matchState}</b></span><span class="match-round">BRASILEIRÃO · RODADA ${state.round}</span></div>
   <div class="match-summary"><div class="score-line"><div class="team-side"><span class="mini-crest">RV</span><span>RIO VERDE</span></div><span class="score-number" id="homeScore">${home}</span><span class="score-dash">:</span><span class="score-number" id="awayScore">${away}</span><div class="team-side away"><span class="mini-crest opponent">AN</span><span>ATLÉTICO NORTE</span></div></div><div class="match-meta-row"><span class="live-min" id="minuteLabel">${minute}</span><span id="matchFeed">${latest}</span><span class="match-location">◉ Estádio Aurora</span></div></div>
  </section>
  <aside class="match-aside">
   <section class="surface next-match-card"><div class="card-heading"><div><span class="section-kicker">PRÓXIMO DESAFIO</span><h3>Atlético Norte</h3></div><span class="opponent-crest">AN</span></div><p class="muted-line">Brasileirão · Rodada ${state.round} <span>•</span> Estádio Aurora</p><div class="opponent-stats"><div><small>POSIÇÃO</small><b>1º</b></div><div><small>FORMA</small><b class="good-form">V E V V D</b></div><div><small>FORÇA</small><b>79</b></div></div><button class="primary-button match-action" data-action="match">${action}<span>↗</span></button>
   </section>
   <section class="surface team-form-card"><div class="card-heading"><div><span class="section-kicker">RIO VERDE FC</span><h3>Momento da equipe</h3></div><span class="form-rating">${state.points} <small>PTS</small></span></div><div class="form-bars"><i class="win">V</i><i class="draw">E</i><i class="win">V</i><i class="loss">D</i><i class="win">V</i></div><p class="muted-line">7º lugar <span>•</span> Objetivo: Libertadores</p></section>
   <section class="surface quick-actions-card"><div class="quick-title">ACESSO RÁPIDO</div><div class="quick-actions"><button data-go="elenco"><span>♙</span> Elenco <b>↗</b></button><button data-go="taticas"><span>⌗</span> Táticas <b>↗</b></button><button data-go="treino"><span>↗</span> Treino <b>↗</b></button></div></section>
  </aside>
 </div>
 <section class="stats-strip"><div class="stat-cell"><div class="stat-label">ORÇAMENTO DISPONÍVEL</div><div class="stat-value"><strong>€ ${state.budget.toFixed(1)}M</strong><span>↑ 2.4%</span></div><small>Ver finanças</small></div><div class="stat-cell"><div class="stat-label">VALOR DO ELENCO</div><div class="stat-value"><strong>€ 42.8M</strong></div><small>14 jogadores</small></div><div class="stat-cell"><div class="stat-label">MORAL DO ELENCO</div><div class="stat-value"><strong>82<span>/100</span></strong></div><small>Bom ambiente</small></div><div class="stat-cell"><div class="stat-label">PRÓXIMO TREINO</div><div class="stat-value"><strong>${state.training<0?'Não definido':'Programado'}</strong></div><small>${state.training<0?'Escolha uma sessão':'Sessão desta semana'}</small></div></section>
 <section class="news-ticker"><span>✦ NOTÍCIAS DO CLUBE</span><p>${state.ended?'A rodada foi concluída. A diretoria acompanha de perto a evolução da equipe.':'A equipe encerrou a preparação. O treinador Marcos Ribeiro acredita em um bom resultado hoje.'}</p><button data-go="liga">Ver campeonato ↗</button></section>`;
}

