function trainingHTML(){
 const sessions=[['⚡','Preparação física','Melhore o condicionamento e a resistência do grupo.','+ Energia',3],['◎','Finalizações','Aprimore a precisão e a tomada de decisão no ataque.','+ Ataque',1],['⌗','Organização tática','Treine posicionamento, movimentação e cobertura.','+ Tática',2],['✦','Bolas paradas','Ensaios ofensivos e defensivos em faltas e escanteios.','+ Estratégia',3],['♙','Posse de bola','Controle do ritmo e circulação sob pressão.','+ Técnica',4],['♡','Recuperação','Diminua o desgaste e recupere jogadores cansados.','+ Condição',5]];
 return `<div class="screen-title-row"><div><h2>Plano semanal</h2><p>Escolha uma sessão para preparar o próximo compromisso.</p></div><span class="position-tag">SEMANA ${state.round} · 1 SESSÃO DISPONÍVEL</span></div><div class="training-grid">${sessions.map(([icon,name,desc,gain,i])=>`<article class="training-card ${state.training===i?'training-selected':''}"><span class="training-icon">${icon}</span><h3>${name}</h3><p>${desc}</p><div class="training-foot"><span>${gain}</span><button data-training="${i}">${state.training===i?'SELECIONADO':'ESCOLHER'}</button></div></article>`).join('')}</div><div class="training-summary"><div class="surface"><small>SESSÃO DA SEMANA</small><strong>${state.training<0?'Ainda não escolhida':sessions[state.training][1]}</strong></div><div class="surface"><small>INTENSIDADE</small><strong>${state.training===0?'Alta':state.training===5?'Leve':'Moderada'}</strong></div><div class="surface"><small>IMPACTO NO ELENCO</small><strong><span>${state.training<0?'Escolha um treino para ver o impacto.':sessions[state.training][3]+' para a equipe'}</span></strong></div></div>`;
}
function leagueHTML(){
 const table=initialTable.map(([club,pts])=>[club,pts]);
 table[6][1]=state.points;
 if(state.played){
  const result=state.homeScore>state.awayScore?3:state.homeScore===state.awayScore?1:0;
  table[6][1]=Math.max(0,9+result);
 }
 table.sort((a,b)=>b[1]-a[1]);
 return `<div class="screen-title-row"><div><h2>Brasileirão · Série A</h2><p>Classificação e próximos jogos da temporada 2025/26.</p></div><span class="position-tag">RODADA ${state.round} DE 38</span></div><div class="league-layout"><section class="surface"><span class="section-kicker">CLASSIFICAÇÃO</span><table class="league-table"><thead><tr><th>#</th><th>CLUBE</th><th>PTS</th><th class="hide-mobile">J</th><th class="hide-mobile">SG</th></tr></thead><tbody>${table.map(([club,pts],i)=>`<tr class="${club==='Rio Verde FC'?'our-club':''}"><td>${i+1}</td><td><span class="league-club"><span class="table-dot ${i>6?'red':''}">${club.split(' ').map(x=>x[0]).slice(0,2).join('')}</span>${club}</span></td><td>${pts}</td><td class="hide-mobile">${club==='Rio Verde FC'?6:6}</td><td class="hide-mobile">${club==='Rio Verde FC'?'+2':i<4?'+4':'-2'}</td></tr>`).join('')}</tbody></table><p class="table-hint">As quatro primeiras equipes se classificam para a Libertadores.</p></section><aside class="league-side"><section class="surface"><span class="section-kicker">JOGOS DA RODADA</span><div class="fixture-row"><b>Rio Verde FC</b><span>HOJE · 19:00</span><b>Atlético Norte</b></div><div class="fixture-row"><b>União da Serra</b><span>HOJE · 21:30</span><b>Porto Azul</b></div><div class="fixture-row"><b>Estrela do Sul</b><span>AMANHÃ · 16:00</span><b>Ferroviária</b></div></section><section class="surface"><span class="section-kicker">OBJETIVO DA DIRETORIA</span><h3 class="league-goal">Classificar para a Libertadores</h3><p class="muted-line">O Rio Verde está ${table.findIndex(x=>x[0]==='Rio Verde FC')+1}º. A temporada tem 38 rodadas.</p><div class="season-progress"><i style="width:${Math.max(12,((38-state.round)/38)*100)}%"></i></div></section></aside></div>`;
}

function bindView(){
 $$('[data-view]').forEach(button=>button.onclick=()=>setView(button.dataset.view));
 $$('[data-go]').forEach(button=>button.onclick=()=>setView(button.dataset.go));
 $$('[data-formation]').forEach(button=>button.onclick=()=>{state.formation=button.dataset.formation;save();render()});
 $$('[data-mentality]').forEach(button=>button.onclick=()=>{state.mentality=button.dataset.mentality;save();render()});
 $$('[data-pressing]').forEach(button=>button.onclick=()=>{state.pressing=button.dataset.pressing;save();render()});
 $$('[data-training]').forEach(button=>button.onclick=()=>{state.training=Number(button.dataset.training);save();render();toast('Treino da semana atualizado.')});
 $$('[data-pick]').forEach(button=>button.onclick=()=>selectPlayer(Number(button.dataset.pick)));
 $$('[data-action]').forEach(button=>button.onclick=()=>{
  const action=button.dataset.action;
  if(action==='match')handleMatch();
  if(action==='save-tactics'){save();toast('Tática salva. A equipe está pronta!')}
  if(action==='auto-tactic'){state.lineup=Array.from({length:11},(_,i)=>i);save();render();toast('Escalação recomendada aplicada.')}
  if(action==='reset-squad'){state.lineup=Array.from({length:11},(_,i)=>i);state.selected=null;save();render();toast('Escalação inicial restaurada.')}
 });
}
function selectPlayer(index){
 if(state.selected===null){state.selected=index;render();return}
 const first=state.selected;state.selected=null;
 const a=state.lineup.indexOf(first),b=state.lineup.indexOf(index);
 if(a>=0&&b>=0){[state.lineup[a],state.lineup[b]]=[state.lineup[b],state.lineup[a]]}
 else if(a>=0&&b<0){state.lineup[a]=index}
 else if(a<0&&b>=0){state.lineup[b]=first}
 else {toast('Selecione um titular e um reserva para trocar.');render();return}
 save();render();toast('Substituição na escalação realizada.');
}
function handleMatch(){
 if(state.ended){state.round=state.round>=38?1:state.round+1;state.played=false;state.ended=false;state.minute=0;state.homeScore=0;state.awayScore=0;state.events=[];state.feed='O elenco está concentrado. A torcida já começa a chegar ao estádio.';save();render();toast(`Preparação para a rodada ${state.round} iniciada.`);return}
 if(state.playing){state.playing=false;clearInterval(matchTimer);render();toast('Partida pausada.');return}
 if(!state.played){state.played=true;state.minute=0;state.homeScore=0;state.awayScore=0;state.events=[];state.feed='Bola rolando no Estádio Aurora!';}
 state.playing=true;render();
 matchTimer=setInterval(()=>{
  if(!state.playing)return;
  state.minute+=3;
  if(Math.random()<.13){const homeChance=Math.random()<.54+(state.mentality==='Ofensiva'?.09:state.mentality==='Defensiva'?-.08:0);if(homeChance)state.homeScore++;else state.awayScore++;state.feed=homeChance?`GOL DO RIO VERDE! ${state.lineup[9]!==undefined?roster[state.lineup[9]].name:'O atacante'} balança a rede!`:'Gol do Atlético Norte. Ainda há tempo para buscar o resultado.';state.events.push(state.feed);}
  if(state.minute>=90){state.minute=90;state.playing=false;state.ended=true;clearInterval(matchTimer);const result=state.homeScore>state.awayScore?3:state.homeScore===state.awayScore?1:0;state.points+=result;roster.slice(0,11).forEach(p=>p.condition=Math.max(55,p.condition-5));save();}
  updateMatch();
 },900);
}
function updateMatch(){
 const minute=$('#minuteLabel'),home=$('#homeScore'),away=$('#awayScore'),feed=$('#matchFeed');
 if(minute)minute.textContent=state.ended?'FIM':`${state.minute}’`;
 if(home)home.textContent=state.homeScore;
 if(away)away.textContent=state.awayScore;
 if(feed)feed.textContent=state.feed;
 const tag=$('.live-tag b');if(tag)tag.textContent=state.ended?'PARTIDA ENCERRADA':'AO VIVO';
 const action=$('.match-action');if(action)action.innerHTML=`${state.playing?'Pausar partida':state.ended?'Próxima rodada':'Começar partida'}<span>↗</span>`;
 if(state.ended){save();toast(`Fim de jogo: Rio Verde ${state.homeScore} x ${state.awayScore} Atlético Norte.`)}
}
function setupCanvas(){
 const canvas=$('#matchCanvas');if(!canvas)return;
 const resize=()=>{const rect=canvas.getBoundingClientRect();const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(rect.width*dpr));canvas.height=Math.max(1,Math.floor(rect.height*dpr));ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0)};
 resize();window.addEventListener('resize',resize,{passive:true});
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 function paint(time){if(!ctx||!canvas.isConnected)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;
  const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#18251d');sky.addColorStop(.48,'#263b2b');sky.addColorStop(1,'#15301d');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
  for(let i=0;i<30;i++){const x=i*w/30;ctx.fillStyle=i%2?'#ffffff08':'#b8e4a408';ctx.fillRect(x,h*.38,w/30+1,h*.62)}
  ctx.fillStyle='#d5dfce';ctx.globalAlpha=.35;ctx.fillRect(w*.08,h*.56,w*.84,1);ctx.strokeStyle='#d5dfce';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(w*.5,h*.72,w*.115,h*.12,0,0,Math.PI*2);ctx.stroke();ctx.strokeRect(w*.28,h*.57,w*.44,h*.18);ctx.strokeRect(w*.39,h*.57,w*.22,h*.08);ctx.globalAlpha=1;
  for(let i=0;i<120;i++){const x=(i*73%w),y=h*(.12+(i*29%30)/100);ctx.fillStyle=i%3?'#d9e3ca':'#d6f58b';ctx.globalAlpha=.16+(i%5)*.045;ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;
  const positions=state.playing?[[.5,.84],[.28,.75],[.43,.78],[.59,.78],[.73,.72],[.34,.66],[.54,.68],[.66,.61],[.3,.57],[.52,.59],[.7,.54],[.47,.73],[.58,.65]]:[[.5,.83],[.3,.76],[.43,.78],[.58,.78],[.71,.73],[.38,.67],[.51,.68],[.64,.63],[.34,.58],[.53,.59],[.69,.55],[.49,.72],[.58,.64]];
  const offset=state.playing?Math.sin(time/460)*.012:0;
  positions.forEach(([px,py],i)=>{const x=w*(px+offset*(i%2?1:-1)),y=h*py;ctx.beginPath();ctx.fillStyle=i<11?'#d6f58b':'#e88967';ctx.arc(x,y,Math.max(3,Math.min(7,w/75)),0,Math.PI*2);ctx.fill();ctx.strokeStyle='#152017';ctx.lineWidth=1;ctx.stroke();if(i===9||i===4){ctx.fillStyle='#f4f3db';ctx.font=`${Math.max(6,w/55)}px sans-serif`;ctx.fillText(i===9?'9':'7',x-2,y+2)}});
  const bx=w*(state.playing?.48+Math.sin(time/700)*.12:.52),by=h*(state.playing?.71+Math.cos(time/620)*.035:.73);ctx.beginPath();ctx.fillStyle='#fff7dd';ctx.arc(bx,by,3,0,Math.PI*2);ctx.fill();
  if(!reduced)raf=requestAnimationFrame(paint);
 }
 if(raf)cancelAnimationFrame(raf);paint(0);if(!reduced)raf=requestAnimationFrame(paint);
}
function init(){
 $$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view==='inicio'));
 $('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');
 $('#inboxButton').onclick=()=>$('#modalBackdrop').classList.add('open');
 $('#modalClose').onclick=$('#modalOkay').onclick=()=>$('#modalBackdrop').classList.remove('open');
 $('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')e.currentTarget.classList.remove('open')};
 $('#nextAction').onclick=()=>{if(state.ended)handleMatch();else if(state.playing){toast('A partida está em andamento.');setView('inicio')}else{setView('taticas');toast('Confira a escalação antes de começar.')}};
 $('.settings-button').onclick=()=>toast('Configurações: seu progresso é salvo automaticamente neste dispositivo.');
 $('.more-button').onclick=()=>toast('Treinador Marcos Ribeiro · Rio Verde FC');
 render();
}
document.addEventListener('DOMContentLoaded',init);

