// Aurora Manager — jogo de gestão de futebol responsivo.
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const roster=[['Lucas Andrade','GL',1,78],['Rafael Nunes','LD',2,74],['Caio Martins','ZAG',3,76],['Bruno Lima','ZAG',4,79],['Igor Santos','LE',6,73],['Pedro Henrique','VOL',5,77],['Matheus Costa','MC',8,81],['Enzo Carvalho','MEI',10,83],['Gabriel Rocha','PD',7,79],['João Pedro','ATA',9,82],['Vitor Oliveira','PE',11,78],['Davi Ferreira','ATA',19,74],['Felipe Azevedo','MC',18,75],['André Luiz','ZAG',14,72]].map(([name,pos,num,rating],i)=>({name,pos,num,rating,condition:[94,91,87,90,93,84,88,95,89,86,92,100,100,100][i]}));
const initialTable=[['Atlético Norte',15],['União da Serra',14],['Porto Azul',13],['Estrela do Sul',12],['Ferroviária',11],['Real Central',10],['Rio Verde FC',9],['Náutico Imperial',8],['Vila Nova',7],['Santa Cruz',6]];
const formations={'4-3-3':[[50,89],[17,72],[39,77],[61,77],[83,72],[36,57],[50,60],[64,57],[18,31],[50,23],[82,31]],'4-4-2':[[50,89],[17,72],[39,77],[61,77],[83,72],[17,52],[39,59],[61,59],[83,52],[37,29],[63,29]],'3-5-2':[[50,89],[27,73],[50,78],[73,73],[12,53],[31,58],[50,54],[69,58],[88,53],[37,29],[63,29]],'4-2-3-1':[[50,89],[17,72],[39,77],[61,77],[83,72],[40,62],[60,62],[22,42],[50,38],[78,42],[50,23]]};
const storageKey='aurora-manager-save';
let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')||{}}catch{}
const state={view:'inicio',round:saved.round||7,budget:saved.budget??12.5,points:saved.points??9,formation:saved.formation||'4-3-3',mentality:saved.mentality||'Equilibrado',pressing:saved.pressing||'Médio',training:saved.training??-1,playing:false,ended:!!saved.ended,played:!!saved.played,minute:saved.minute||0,homeScore:saved.homeScore||0,awayScore:saved.awayScore||0,events:saved.events||[],feed:saved.feed||'O elenco está concentrado. A torcida já começa a chegar ao estádio.',selected:null,lineup:Array.isArray(saved.lineup)&&saved.lineup.length===11?saved.lineup:Array.from({length:11},(_,i)=>i)};
let matchTimer=null,raf=0,ctx=null,toastTimer=null;
function save(){try{localStorage.setItem(storageKey,JSON.stringify({...state,playing:false}))}catch{}}
function toast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
const titles={inicio:['VISÃO GERAL','Bom dia, Mister','A semana está só começando. Vamos fazer valer.'],elenco:['MEU ELENCO','Elenco principal','Conheça seus atletas e monte a equipe ideal.'],taticas:['TÁTICAS','Quadro tático','Defina a formação e a identidade de jogo do Rio Verde.'],treino:['TREINAMENTO','Plano semanal','Prepare a equipe para o próximo compromisso.'],liga:['CAMPEONATO','Brasileirão · Série A','Acompanhe a classificação e os próximos jogos.']};
function setView(view){if(!titles[view])return;state.view=view;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumbTitle').textContent=titles[view][0];$('#pageTitle').innerHTML=view==='inicio'?'Bom dia, Mister <span>✦</span>':titles[view][1];$('#pageSubtitle').textContent=titles[view][2];$('#sidebar').classList.remove('open');render()}
function render(){const root=$('#viewContent');if(!root)return;root.innerHTML=({inicio:dashboardHTML,elenco:squadHTML,taticas:tacticsHTML,treino:trainingHTML,liga:leagueHTML}[state.view]());bindView();if(state.view==='inicio')setupCanvas()}
function dashboardHTML(){
 const minute=state.ended?'FIM':state.playing?`${state.minute}’`:'HOJE · 19:00',matchState=state.ended?'PARTIDA ENCERRADA':state.playing?'AO VIVO':'DIA DE JOGO';
 const home=state.played?state.homeScore:'—',away=state.played?state.awayScore:'—';
 const action=state.playing?'Pausar partida':state.ended?'Próxima rodada':'Começar partida';
 return `<div class="dashboard-grid"><section class="match-card"><canvas id="matchCanvas" class="match-canvas" aria-label="Animação de partida de futebol"></canvas><div class="match-topline"><span class="live-tag"><i></i><b>${matchState}</b></span><span class="match-round">BRASILEIRÃO · RODADA ${state.round}</span></div><div class="match-summary"><div class="score-line"><div class="team-side"><span class="mini-crest">RV</span><span>RIO VERDE</span></div><span class="score-number" id="homeScore">${home}</span><span class="score-dash">:</span><span class="score-number" id="awayScore">${away}</span><div class="team-side away"><span class="mini-crest opponent">AN</span><span>ATLÉTICO NORTE</span></div></div><div class="match-meta-row"><span class="live-min" id="minuteLabel">${minute}</span><span id="matchFeed">${state.events.at(-1)||state.feed}</span><span class="match-location">◉ Estádio Aurora</span></div></div></section><aside class="match-aside"><section class="surface next-match-card"><div class="card-heading"><div><span class="section-kicker">PRÓXIMO DESAFIO</span><h3>Atlético Norte</h3></div><span class="opponent-crest">AN</span></div><p class="muted-line">Brasileirão · Rodada ${state.round} <span>•</span> Estádio Aurora</p><div class="opponent-stats"><div><small>POSIÇÃO</small><b>1º</b></div><div><small>FORMA</small><b class="good-form">V E V V D</b></div><div><small>FORÇA</small><b>79</b></div></div><button class="primary-button match-action" data-action="match">${action}<span>↗</span></button></section><section class="surface team-form-card"><div class="card-heading"><div><span class="section-kicker">RIO VERDE FC</span><h3>Momento da equipe</h3></div><span class="form-rating">${state.points} <small>PTS</small></span></div><div class="form-bars"><i class="win">V</i><i class="draw">E</i><i class="win">V</i><i class="loss">D</i><i class="win">V</i></div><p class="muted-line">7º lugar <span>•</span> Objetivo: Libertadores</p></section><section class="surface quick-actions-card"><div class="quick-title">ACESSO RÁPIDO</div><div class="quick-actions"><button data-go="elenco"><span>♙</span> Elenco <b>↗</b></button><button data-go="taticas"><span>⌗</span> Táticas <b>↗</b></button><button data-go="treino"><span>↗</span> Treino <b>↗</b></button></div></section></aside></div><section class="stats-strip"><div class="stat-cell"><div class="stat-label">ORÇAMENTO DISPONÍVEL</div><div class="stat-value"><strong>€ ${state.budget.toFixed(1)}M</strong><span>↑ 2.4%</span></div><small>Ver finanças</small></div><div class="stat-cell"><div class="stat-label">VALOR DO ELENCO</div><div class="stat-value"><strong>€ 42.8M</strong></div><small>14 jogadores</small></div><div class="stat-cell"><div class="stat-label">MORAL DO ELENCO</div><div class="stat-value"><strong>82<span>/100</span></strong></div><small>Bom ambiente</small></div><div class="stat-cell"><div class="stat-label">PRÓXIMO TREINO</div><div class="stat-value"><strong>${state.training<0?'Não definido':'Programado'}</strong></div><small>${state.training<0?'Escolha uma sessão':'Sessão desta semana'}</small></div></section><section class="news-ticker"><span>✦ NOTÍCIAS DO CLUBE</span><p>${state.ended?'A rodada foi concluída. A diretoria acompanha de perto a evolução da equipe.':'A equipe encerrou a preparação. O treinador Marcos Ribeiro acredita em um bom resultado hoje.'}</p><button data-go="liga">Ver campeonato ↗</button></section>`;
}
function squadHTML(){return `<div class="screen-title-row"><div><h2>Elenco principal</h2><p>Gerencie seus atletas e monte a equipe ideal.</p></div><button class="secondary-button" data-action="reset-squad">↺ Restaurar equipe</button></div><div class="squad-layout"><section class="surface"><table class="squad-table"><thead><tr><th>JOGADOR</th><th>POS.</th><th class="hide-mobile">Nº</th><th>NOTA</th><th>FÍSICO</th><th>TIME</th></tr></thead><tbody>${roster.map((p,i)=>{const starter=state.lineup.includes(i);return `<tr class="${state.selected===i?'selected-player':''}" data-player="${i}"><td class="player-name"><span class="player-avatar ${i%4===0?'warm':''}">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span>${p.name}</td><td><span class="position-tag">${p.pos}</span></td><td class="hide-mobile">${p.num}</td><td><span class="rating ${p.rating>=78?'high':''}">${p.rating}</span></td><td><span class="condition ${p.condition<65?'low':''}"><i style="width:${p.condition}%"></i></span> ${p.condition}%</td><td><button class="squad-select ${starter?'in-team':''}" data-pick="${i}">${starter?'TITULAR':'RESERVA'}</button></td></tr>`}).join('')}</tbody></table><p class="table-hint">Dica: selecione um titular e depois um reserva para fazer uma substituição.</p></section><aside class="squad-side"><section class="surface"><span class="section-kicker">VISÃO DO ELENCO</span><div class="chemistry"><div class="chemistry-ring">82</div><div><strong>Entrosamento</strong><p>Boa conexão entre os setores</p></div></div><div class="role-list"><div><span>Goleiros</span><b>1</b><i><em style="width:75%"></em></i></div><div><span>Defensores</span><b>4</b><i><em style="width:82%"></em></i></div><div><span>Meio-campistas</span><b>4</b><i><em style="width:88%"></em></i></div><div><span>Atacantes</span><b>5</b><i><em style="width:79%"></em></i></div></div></section><section class="surface"><span class="section-kicker">DESTAQUE DO TIME</span><div class="star-player"><span class="player-avatar warm">EC</span><div><strong>Enzo Carvalho</strong><small>Meia · Nota 83</small></div><b>83</b></div><p class="muted-line">O maestro do meio-campo. Em ótima forma nesta semana.</p></section></aside></div>`}
