function trainingHTML(){const sessions=[['⚽','Finalização','Aprimore a precisão e a tomada de decisão perto do gol.','Ataque'],['⌖','Organização defensiva','Compactação, cobertura e posicionamento sem a bola.','Defesa'],['↗','Preparação física','Resistência e velocidade para manter o ritmo durante os 90 minutos.','Físico'],['⌗','Posse de bola','Passe curto, movimentação e controle do meio-campo.','Técnica'],['✦','Bolas paradas','Jogadas ensaiadas para aproveitar cada escanteio e falta.','Estratégia'],['◉','Recuperação','Reduza o desgaste e recupere a condição física do elenco.','Recuperação']];return `<div class="screen-title-row"><div><h2>Plano semanal</h2><p>Escolha uma sessão para preparar o time para a rodada.</p></div><span class="position-tag">SEMANA ${state.round} · 1 SESSÃO DISPONÍVEL</span></div><div class="training-grid">${sessions.map(([icon,name,desc,tag],i)=>`<article class="training-card"><span class="training-icon">${icon}</span><h3>${name}</h3><p>${desc}</p><div class="training-foot"><span>${state.training===i?'✓ Treino selecionado':tag}</span><button data-training="${i}">${state.training===i?'SELECIONADO':'ESCOLHER'}</button></div></article>`).join('')}</div><div class="training-summary"><section class="surface"><small>INTENSIDADE DA SEMANA</small><strong>${state.training===-1?'Sem treino':state.training===2?'Alta':state.training===5?'Leve':'Moderada'}</strong></section><section class="surface"><small>CONDIÇÃO MÉDIA</small><strong>91<span>/100</span></strong></section><section class="surface"><small>PRÓXIMO JOGO</small><strong>Rodada ${state.round}<span> · hoje</span></strong></section></div>`}
function leagueHTML(){const table=[...initialTable];if(state.points!==9)table[6][1]=state.points;table.sort((a,b)=>b[1]-a[1]);return `<div class="screen-title-row"><div><h2>Classificação</h2><p>Brasileirão · Série A · Temporada 2025/26</p></div><span class="position-tag">RODADA ${state.round} DE 38</span></div><div class="league-layout"><section class="surface"><table class="league-table"><thead><tr><th>#</th><th>CLUBE</th><th>PTS</th><th class="hide-mobile">J</th><th class="hide-mobile">V-E-D</th><th class="hide-mobile">SG</th></tr></thead><tbody>${table.map(([club,pts],i)=>`<tr class="${club==='Rio Verde FC'?'our-club':''}"><td>${i+1}</td><td><span class="league-club"><span class="table-dot ${i===0?'red':''}">${club.split(' ').map(x=>x[0]).slice(0,2).join('')}</span>${club}</span></td><td>${pts}</td><td class="hide-mobile">${state.round-1}</td><td class="hide-mobile">${Math.max(1,Math.floor(pts/3))}-${Math.floor(pts%3)}-${Math.max(0,state.round-1-Math.floor(pts/3)-Math.floor(pts%3))}</td><td class="hide-mobile">${club==='Rio Verde FC'?'+2':i<4?'+5':'-3'}</td></tr>`).join('')}</tbody></table><p class="table-hint">Os quatro primeiros garantem vaga na Libertadores.</p></section><aside class="league-side"><section class="surface"><span class="section-kicker">PRÓXIMOS JOGOS</span><div class="fixture-row"><span>RIO VERDE <b>×</b> ATLÉTICO NORTE</span><span>HOJE · 19:00</span></div><div class="fixture-row"><span>UNIÃO DA SERRA <b>×</b> PORTO AZUL</span><span>HOJE · 21:30</span></div><div class="fixture-row"><span>ESTRELA DO SUL <b>×</b> FERROVIÁRIA</span><span>AMANHÃ · 16:00</span></div></section><section class="surface"><span class="section-kicker">OBJETIVO DA DIRETORIA</span><h3>Vaga na Libertadores</h3><p class="muted-line">O clube espera terminar entre os 6 primeiros. Mantenha o bom trabalho, Mister.</p><div class="season-progress"><i style="width:${Math.max(15,Math.min(90,state.points*4))}%"></i></div></section></aside></div>`}

