const assert = require('node:assert/strict');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  assert.match(await page.title(), /Aurora Manager/);
  assert.equal(await page.locator('#viewContent .match-card').count(), 1, 'dashboard renders');
  // Navigate all key sections and exercise their stateful controls.
  await page.locator('[data-view="elenco"]').click();
  assert.equal(await page.locator('[data-pick]').count(), 14, 'full squad renders');
  await page.locator('[data-pick="0"]').click();
  await page.locator('[data-pick="11"]').click();
  assert.match(await page.locator('[data-pick="11"]').innerText(), /TITULAR/);
  await page.locator('[data-view="taticas"]').click();
  await page.locator('[data-formation="3-5-2"]').click();
  await page.locator('[data-mentality="Ofensiva"]').click();
  await page.locator('[data-pressing="Alto"]').click();
  assert.equal(await page.locator('.formation-label').innerText(), '3-5-2 · RIO VERDE FC');
  await page.locator('[data-view="treino"]').click();
  await page.locator('[data-training="5"]').click();
  assert.match(await page.locator('.training-summary').innerText(), /Leve/);
  await page.locator('[data-view="liga"]').click();
  assert.equal(await page.locator('.league-table tbody tr').count(), 10);
  await page.reload({ waitUntil: 'networkidle' });
  await page.locator('[data-view="taticas"]').click();
  assert.equal(await page.locator('.formation-label').innerText(), '3-5-2 · RIO VERDE FC', 'tactics persist after reload');
  await page.locator('[data-view="inicio"]').click();
  await page.locator('[data-action="match"]').click();
  await page.waitForTimeout(1400);
  assert.match(await page.locator('#minuteLabel').innerText(), /[3-9]’/);
  await page.locator('[data-action="match"]').click();
  assert.equal(await page.locator('.live-tag b').innerText(), 'DIA DE JOGO', 'match can be paused');
  await page.locator('#inboxButton').click();
  assert.equal(await page.locator('.modal-backdrop.open').count(), 1, 'notification dialog opens');
  await page.locator('#modalOkay').click();
  assert.equal(await page.locator('.modal-backdrop.open').count(), 0, 'notification dialog closes');
  // Reset to a clean career before the final screenshot pair.
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.screenshot({ path: '/tmp/opencode/aurora-desktop.jpg', type: 'jpeg', quality: 85, fullPage: true });
  const desktopOverflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
  await page.setViewportSize({ width: 390, height: 844 });
  await page.reload({ waitUntil: 'networkidle' });
  const mobileOverflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
  await page.screenshot({ path: '/tmp/opencode/aurora-mobile.jpg', type: 'jpeg', quality: 85, fullPage: true });
  assert.equal(errors.length, 0, `browser errors: ${errors.join('; ')}`);
  console.log(JSON.stringify({ tests: 'passed', consoleErrors: errors, desktopOverflow, mobileOverflow, screenshots: ['/tmp/opencode/aurora-desktop.jpg', '/tmp/opencode/aurora-mobile.jpg'] }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exitCode = 1; });

